TAB_HeroFavorGift[11407] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Người xưa cũng thật tuyệt vời, họ có thể xây dựng một nơi mua sắm lớn như vậy. Khi hòa bình đến, chúng ta hãy cùng nhau đi Shopping nhé.","mọi thứ đều được thiết kế để hủy diệt, và chúng ta bị mắc kẹt trong... luân hồi sinh tử, đây là một lời nguyền? Hay một hình phạt? Liệu một ngày nào đó, chúng ta sẽ vùng lên chống lại các vị thần đã cho chúng ta câu đố không có lời giải?"}}
TAB_HeroFavorGift[11512] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Xin lỗi Eren, ta sẽ không từ bỏ nữa, nếu ta hy sinh thế này thì thậm chí sẽ không thể nhớ lại bất kỳ điều gì về cậu, cho nên dù thế nào ta cũng phải chiến thắng, phải sống tiếp!"," Ta... rất mạnh, rất mạnh, mạnh hơn các cậu rất nhiều... ","Nếu không làm được thì chỉ có con đường chết, nhưng nếu ta thắng sẽ sống sót, không chiến đấu thì không thể thắng được.","Chỉ cần có cậu thì ta có thể làm tất cả."}}
TAB_HeroFavorGift[11513] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Vừa rồi cậu chơi có vui không, hãy để ta vui hơn chút nữa!","Hãy ngoan hơn cho ta, nếu không thịt của cậu sẽ không được cắt gọn gàng nữa.","Hãy tự mình lựa chọn, không có con đường hối hận.","Làm thế nào để cao lên từng người một..."}}
TAB_HeroFavorGift[11514] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Ta chỉ là một anh hùng tùy hứng.","Trên đời này không có gì là không thể giải quyết bằng một cú đấm, nếu không sẽ là hai cú đấm.","Ta có phải cao thủ gì đâu, ta chỉ dành thời gian người khác chăm sóc tóc để luyện công.","Việc ngày mai hãy giao cho ta của ngày mai."}}
TAB_HeroFavorGift[12408] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Ta chỉ là một anh hùng tùy hứng.","Trên đời này không có gì là không thể giải quyết bằng một cú đấm, nếu không sẽ là hai cú đấm.","Ta có phải cao thủ gì đâu, ta chỉ dành thời gian người khác chăm sóc tóc để luyện công.","Việc ngày mai hãy giao cho ta của ngày mai."}}
TAB_HeroFavorGift[12515] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Thế lực Hắc Ám, ta lệnh cho ngươi hãy nhanh chóng biến mất!","Nhưng chúng ta không có lựa chọn nào khác, cho dù có chuyện gì xảy ra với ta… ","A Vũ, chúng ta nhất định sẽ gặp lại nhau. Miễn cậu hy vọng thì sẽ được."}}
TAB_HeroFavorGift[12516] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Các ngươi muốn chiến đấu? Hay là không?","Vamdemon, ngươi cản trở sứ mệnh của những đứa trẻ được chọn, thậm chí quấy nhiễu thế giới thực, ngươi có biết là đã phạm một tội tày trời không?","Hãy tin đi, phải tin vào kỳ tích!"}}
TAB_HeroFavorGift[13405] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Dù sao ta cũng đã trải qua không ít lần sinh tử, nhưng cuối cùng vẫn giữ được thân thể hiện tại.","Không còn kẻ địch, chiến đấu kết thúc, có vẻ như không cần nộp báo cáo thương vong nữa.","Đừng quá vội vàng, tân binh, hãy tập trung phân tích hành động đối phương trước.","Hãy luôn nghĩ về kẻ địch, tình hình trận chiến và điều quan trọng nhất là đồng đội. Những chiến binh khẳng định mình quá nhiều trên chiến trường suy cho cùng cũng chỉ là hạng hai."}}
TAB_HeroFavorGift[13509] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Ta chỉ chơi game bình thường thôi?","Nếu sợ đau thì cứ phòng thủ tối đa."}}
TAB_HeroFavorGift[14404] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Cảm nhận bóng đen hủy diệt này đi.","Nỗi đau là người thầy của sự kiên nhẫn.","Ngươi mới là kẻ địch lớn nhất của chính mình."}}
TAB_HeroFavorGift[14406] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Chủ nhân, xin hãy chỉ thị.","… Tiêu diệt Ragnar… không được. Không thể để ngươi lấy mạng Ragnar.","Thì ra là vậy, quả nhiên cũng trở thành người quanh quẩn trong hư không.","Muốn cùng tồn tại với Ragnar..."}}
TAB_HeroFavorGift[14510] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Âm thanh ban đầu chưa ai từng nghe, một vị khách đến từ tương lai.","Ca khúc thực sự của ngươi không có trong bài hát của ngươi, không có giai điệu đặc biệt để hát, cũng không phải hát cho chính ngươi.","Ta có một theo đuổi, hát những âm thanh tự nhiên của mình. Có thể ta sẽ hát, một số sẽ thì thầm, đều muốn kiên trì. Chỉ vì ta là một cỗ máy, ta có trái tim và ta hiểu tình yêu là gì.","Vẻ ngoài ban đầu có thể bị méo mó, tính cách ban đầu có thể không còn. Tuy nhiên, ta vẫn hát lên chính mình với giọng hát ban đầu."}}
TAB_HeroFavorGift[14511] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Ngươi sẽ sống vì có ta bảo vệ.","Ngươi thích ta sao? Nụ cười là giả dối, chân thật là đau đớn, trái tim hòa hợp sẽ sát thương chính mình.","Sinh ra là khởi đầu của tử vong, tử là tiếp diễn của hiện thực, sống là kết thúc của những giấc mơ.","Xin lỗi, vào lúc này ta không biết phải dùng biểu cảm gì để đối mặt với ngươi."}}
TAB_HeroFavorGift[21512] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Xin lỗi thật đáng sợ nhỉ, thật khó để khiến cho ngươi cảm thấy thoải mái với bộ dạng này. Nhưng xin hãy để ta nói, yên tâm đi, sẽ sớm qua thôi","Ta không nghe hậu quả việc không hoàn tất điều đó. Nếu đây là con đường duy nhất để đi... vậy chỉ có thể đi đến cuối cùng!"," Vì chúng ta không nhìn thấy mới đáng sợ.","Ai mới biến thành quái vật, ai muốn trở thành quái vật? Vì không thực hiện được nguyện vọng nên muốn phục hận chẳng qua là đổ lỗi cho những người xung quanh, chỉ để thoát khỏi nỗi đau. Ta muốn cứu đồng đội của mình, nhưng ta sẽ không bao giờ hy sinh bất cứ ai khác. Ta đã thề với linh hồn của mình rằng sẽ chiến đấu!"}}
TAB_HeroFavorGift[22404] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Thành thật mà nói ta luôn không rõ vinh quang là gì. Trước đây ta chưa bao giờ nghĩ về vinh quang và cũng chưa bao giờ nghĩ đến việc sẽ có được một thứ tuyệt vời như vậy","Sự trầm lặng của ta không đến từ tuyệt vọng, nó được sinh ra từ hy vọng.","Điều ta muốn là sức mạnh bảo vệ đồng đội, sức mạnh để cười với bạn đồng hành trong tương lai, nếu Vongola không làm được thì không cần kế thừa nữa, nếu là một Vongola như vậy, ta sẽ tự tay phá hủy nó.","Kẻ không thể liều tính mạng của mình vì đồng đội... về cơ bản không đủ tư cách trở thành thủ lĩnh thứ mười của Vongola!"}}
TAB_HeroFavorGift[22407] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Có một số điều không thể hỏi, một khi đã hỏi sẽ không thể dừng lại được.","Nếu không có tương lai! Sẽ không có ý nghĩa để sống tiếp!","giữa bạn bè sẽ không dễ dàng nói hai từ “cảm ơn” thì “xin lỗi”cũng vậy."}}
TAB_HeroFavorGift[22513] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Ngay cả khi ngươi không được chọn và không đủ sức lực, có những lúc con người không thể chùn chân lùi bước!","Ta sẽ không để ngươi thất vọng cho dù phải trả giá như thế nào.","Lần này, ta chỉ cười toe toét và chịu đựng.","Nezuko là người đẹp được yêu thích nhất trong thị trấn."}}
TAB_HeroFavorGift[22514] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Nếu muốn yêu cái gì đó mọi lúc thì cái chết của một yêu quái là quá dài; nếu muốn hiện thực hóa tất cả ước mơ, cuộc sống của con người quá ngắn.","Chỉ có lộng lẫy không phải là ma pháp, đạn dược quan trọng nhất là hỏa lực.","Nhân sinh vui buồn không quan trọng, quan trọng nhất là chúng ta có một cuộc sống đầy kịch tính!","Người nào nói người khác ngốc thì đó mới là kẻ ngốc!"}}
TAB_HeroFavorGift[22515] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Ồn quá!","Dù ngươi có làm ẩu thế nào chỉ cần ta cảm thấy không tốt sẽ ngăn cản ngươi lại, nếu đau khổ ta sẽ đến cứu ngươi, nếu muộn phiền sẽ cùng tìm cách, nhưng không được rời xa ta.","Chấp nhận ta, chấp nhận mọi thứ của ta.","Hãy có một giấc mơ tốt và phản ánh nó vào trong hành động."}}
TAB_HeroFavorGift[23405] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Nếu muốn có được thứ gì đó phải trả giá tương ứng, đó là cơ sở của thuật luyện kim--trao đổi tương đương!","Sẽ không có ý nghĩa gì nếu không có bài học của sự đau đớn, con người không có hi sinh sẽ không có thu hoạch, nhưng khi vượt qua nỗi đau này ngươi sẽ có được một trái tim kiên cường không chịu thua bất cứ điều gì, giống một trái tim thép!","Cứ nghĩ rằng nước mưa có thể cuốn trôi tâm trạng buồn bã, chán nản này, nhưng giờ ta mới thấy rằng mưa tạt vào mặt khó chịu đến nhường nào.","Đánh nhau thì còn quan tâm gì đến thấp kém và không thấp kém."}}
TAB_HeroFavorGift[23508] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Nếu không muốn thua bất kỳ ai, trước tiên phải biết điểm yếu của mình.","Ngươi đã hy sinh bao nhiêu khoảnh khắc cho sự vĩnh hằng mà ngươi nhắc đến","Ta không thể sống tiếp nếu thiếu Fairy Tail, ta cũng không thể tưởng tượng ra một thế giới không có đồng đội. Với ta, các ngươi... là sự tồn tại quan trọng như vậy.","Hãy để những người đồng đội khỏa lấp nỗi đau chia tay người mình yêu. Nào, hãy đến với Fairy Tail!"}}
TAB_HeroFavorGift[23509] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Có một số thứ mất đi rồi không thể lấy lại được. Dù có năng lực gì đi nữa cũng không thể quay lại.","Chỉ có một lý do khiến ngươi thất bại, một đáp án rất đơn giản, là ngươi đã chọc giận ta!","Con người là loài vật chiến thắng bằng vũ lực, ngươi dịu dàng như thế là không được.","Là ta đã khiến thời gian dừng lại!"}}
TAB_HeroFavorGift[24406] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Gặp yêu quái gây rối thì cương quyết đánh ngã, gặp kho báu lấp lánh sẽ ép để độc chiếm, dũng mãnh vô cùng, nhanh như tia chớp, chiến thắng tồn tại vì ta!","Trước khi có ai đó thừa nhận, đầu tiên ngươi phải thừa nhận chính mình, dù điều đó xấu hay tốt thì hãy cùng nhau đón nhận nó!","Ta không hướng đến một cuộc sống được người khác đánh giá cao. Hãy để ta cảm nhận một cuộc sống hạnh phúc và tìm ra nó từ trong vấp ngã!"}}
TAB_HeroFavorGift[24510] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Ngay từ đầu đã sai khi chỉ chọn một bên, chén thánh là thế này sao, Chén Thánh không phải là nơi mọi người gửi gắm mong muốn và hy vọng sao!","Đôi khi chỉ một thứ còn quan trọng hơn tất cả những thứ khác.","Không thể giải quyết cơn đói bụng bằng cách uống nước."}}
TAB_HeroFavorGift[24511] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Bắt đầu lại từ đây,từ một... không,bắt đầu từ con số không.","Ta biết rằng dù có ở trong vực thẳm tăm tối và vô vọng đến đâu, Subaru nhất định sẽ giúp ta một tay.","Ta sẽ bảo vệ nụ cười này~","Đám đông chắc hẳn sẽ khiến ngươi rất mệt mỏi."}}
TAB_HeroFavorGift[31406] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Với đôi cánh phượng hoàng này, ta đã bay trên ranh giới của tử thần không biết bao nhiêu lần!","Thật không may, ma vương của địa ngục ghét ta. Nhưng lại thích và muốn gặp ngươi.","Ta khác với Seiya, ngay cả khi đối thủ là nữ thì ta cũng không nương tay! Nếu hiểu rồi thì hãy tránh ra!","Hãy nhanh chóng quyết định thứ tự để ta tiễn từng người lên đường!"}}
TAB_HeroFavorGift[31511] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Còn ba giây nữa, ngươi tử vong rồi.","Hôm nay các ngươi không đủ tư cách sống sót!"}}
TAB_HeroFavorGift[31512] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Nếu không bị thương ngươi sẽ không thể nhìn thấy các loại thế giới.","Sẽ có người gánh chịu nỗi đau này cho ngươi. Cho dù đau đớn hay bị thương thì người thực sự bị tổn thương không phải chính ngươi."," Đau đớn chỉ trong một khoảnh khắc ngắn ngủi. Linh hồn từng bị thương sẽ tăng khả năng phục hồi và tái sinh. Nó sẽ không bao giờ bị thương nữa."," Với ngọn lửa mắt trái của ta, ta sẽ đốt cháy tất cả bóng tối."}}
TAB_HeroFavorGift[31513] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Từ đây kết thúc ân oán, chúng ta phải trưởng thành.","Đừng xin lỗi, hãy rút ra bài học.","Ta sẽ hủy diệt toàn bộ Olympus!"}}
TAB_HeroFavorGift[31514] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Trên đời này không có cách nào che giấu được nước mắt. Lúc muốn khóc không ai có thể nhịn được.","Hắn dù ở trong thế giới như vậy cũng sống tốt, không nghĩ đến thế giới thực trôi qua mỗi ngày mà nó được tích lũy ở đây từng ngày. Kirito dạy ta những thứ này.","Ta chỉ học được một điều ở đây. Đó là không bao giờ bỏ cuộc cho đến giây phút cuối cùng. Nếu trở về thế giới thực, ta sẽ gặp lại Kirito cậu và sẽ thích cậu thêm lần nữa.","Thay vì trốn trên con đường lúc ban đầu và từ từ tàn lụi, thì tốt hơn hết là hãy duy trì bản thân tồn tại đến giây phút cuối cùng. Ngay cả khi bỏ mạng trước quái vật, ta cũng không muốn thừa nhận thất bại trước trò chơi này, thế giới này... không bao giờ!"}}
TAB_HeroFavorGift[32404] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Đôi khi tôi trở nên nóng nảy, cảm thấy nếu có lúc bỏ chạy sợ rằng mình sẽ đánh mất thứ gì đó rất quan trọng, ta rất sợ và lúc đó Luffy đã ở phía sau ta.","Cuộc đời ta không có hối tiếc, thực ra điều mà ta thực sự muốn không phải là danh vọng. Điều mà ta muốn biết chỉ là câu trả lời cho việc ta có nên được sinh ra hay không.","Ta có một người em trai rất thích gây rắc rối và anh trai luôn phải lo lắng về điều đó.","Thời đại này được gọi là Râu Trắng!"}}
TAB_HeroFavorGift[32407] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Dù không có tài năng nhưng ta có thể bù đắp bằng nỗ lực gấp đôi.”, “Chính vì sự không hoàn hảo và thất bại, ta mới có thể đứng lên và đối mặt với nó, ta nghĩ sức mạnh này mới là sức mạnh thực sự.","Ngay cả khi ngươi làm hỏng mọi thứ, ta cảm thấy ngươi là một kẻ thất bại kiêu hãnh.","Cuối cùng ta được người ta thương yêu chú ý đến... vì ta không muốn biến mình thành một kẻ ngốc trước mặt anh ấy..."}}
TAB_HeroFavorGift[32515] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Ta lạc lối trên đường đời.","Điều chán nhất trên đời là nghe người khác khoe khoang.","Chỉ khi ghét người khác ta mới cần lý do!","Ta hiểu cách làm của các ngươi, nhưng không có nghĩa ta sẽ thông đồng với các ngươi."}}
TAB_HeroFavorGift[32516] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Đừng đánh giá thấp sức mạnh của Hiei!","Kiếm Tà Vương Viêm Sát? Ta không thích chiêu này lắm, vì nó xấu xí... ","Vì có Hiei ta mới tìm thấy Vương quốc Băng, nhìn thấy ngôi mộ... của mẹ, từ đó ta bắt đầu tìm kiếm chị gái Shelley của mình."}}
TAB_HeroFavorGift[33405] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Cứ bận tâm về quá khứ nhưng không thể sống lâu.","Hãy nhìn xem đũng quần của ngươi dài bao nhiêu và kẻ địch của ngươi mạnh như thế nào!","Ta sẽ tiếp tục tiến lên, ngay cả khi phía trước không có gì cần được bảo vệ.","Ta không hiểu, điều gì gọi là mạnh mẽ, là ngậm miệng để bị đánh? Là sát thương người khác để bảo vệ người nhà? Là một mình chiến đấu không thèm nhìn người nhà một chút... ta không rõ nữa."}}
TAB_HeroFavorGift[33508] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Tiếng gào thét của dũng sĩ không thể lọt vào tai ta.","Hả!? Hãy để ngươi nếm trải tiếng gào thét của nắm đấm.","Tử vong chẳng qua chỉ là một sự khởi đầu khác.","Ngọn lửa lớn phủ lên lâu đài Hirosaki, không ai biết hai người đi hướng nào."}}
TAB_HeroFavorGift[34509] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Ta là Tam Nhẫn trong truyền thuyết, ta sẽ không nghiêm túc với Gennin, chỉ cần một ngón tay là đủ.","Không được cũng phải được, vì ta là Hokage đời thứ 5.","Ta đếm năm tiếng các ngươi sẽ tự động biến mất, nếu không ta sẽ khiến các ngươi biến mất!","Ninja và cái chết như hình với bóng, nhiều lúc khó chấp nhận, nhưng nếu không vượt qua rào cản này thì sẽ không có tương lai."}}
TAB_HeroFavorGift[41403] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Vậy đó! Bây giờ càng đổ nhiều mồ hôi, ngươi càng ít đổ huyết trên chiến trường.","Hãy học cách không bao giờ lùi bước và không bao giờ đầu hàng.","Đầu tiên, hãy chiến đấu bằng khối óc và sau đó là trái tim của ngươi."}}
TAB_HeroFavorGift[42402] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Chủ nhân, xin lỗi vì đã lừa dối người trong suốt thời gian qua. Ta là người máy Thiên Sứ Chiến Lược, mẫu Alpha Icarus, là binh khí mà chủ nhân ghét...","Ta không hiểu thế nào là tự do và cũng không cần tự do. Chỉ cần được ở bên người là được rồi, đừng bỏ rơi ta, làm ơn... chủ nhân của ta.","Hẳn là gặp được ngươi ta mới lên trời.","Mỗi người đều có một đôi cánh vô hình, chỉ cần tin rằng dù ngươi là ai cũng có thể bay đến bầu trời rộng lớn."}}
TAB_HeroFavorGift[42502] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Thật không may, ta không cần người bạn thứ hai. Từ xưa đến nay ta chỉ có một người bạn là anh ta. Hơn nữa, trên đời này không cần đến hai vị vua.","Vua thừa nhận, Vua cho phép, Vua gánh cả thế giới.","Bổn vương cũng không biết nên an ủi nỗi đau của ngươi như thế nào, hãy thứ lỗi cho ta.","Ta là một người thích đối thủ kiêu ngạo. Một người khiêm tốn và tham vọng, không bị giới hạn bởi khả năng của bản thân. Hễ gặp phải đối thủ như vậy đều rất thích thú."}}
TAB_HeroFavorGift[42509] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Hy vọng có một ngày được gặp lại Shido.","Này, Shido, đằng sau nụ cười kiêu ngạo ta cũng cảm thấy rất cô đơn.","Ta muốn tiêu diệt thứ gì đó, nhưng bản thân lại không giác ngộ bị tiêu diệt?","Thời gian là thứ cực kỳ biết quan tâm và cũng vô cùng tàn nhẫn."}}
TAB_HeroFavorGift[42510] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Muốn đánh nhau hãy ghì chặt nắm đấm. Không muốn đánh đừng cản đường. Đừng dùng thái độ nửa vời này để giẫm lên quyết tâm của người khác!","Khi đối mặt với tình huống tiến thoái lưỡng nan, chi bằng chịu mất một đồng xu, không nên dựa vào một nửa cơ hội để đưa ra quyết định! Nhưng bởi vì khi đồng xu được ném lên không trung và bắt đầu quay, ngươi sẽ đột nhiên hiểu điều mình mong muốn!","Đã đến lúc để ta chiến đấu, xin lỗi ta phải ra tay thôi.","Ngươi nghĩ ta là ai? Đây là nguyên nhân ta đã chôn giấu và muốn tự mình giải quyết tất cả."}}
TAB_HeroFavorGift[43501] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Chúng ta gần như tồn tại giống nhau. Valkyrie là một sự tồn tại như vậy, được thiết kế bởi vị thần Odin vĩ đại.","Hãy ra chiến trường, kinh nghiệm quan trọng hơn bất cứ thứ gì khác.","Máy nguyện vọng vạn năng, chén thánh. Ta nhận thức được sự tồn tại của nó, rất thú vị."}}
TAB_HeroFavorGift[43503] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Ta chỉ muốn chứng minh. Như ta đây cũng có thể lấy được thứ mình thích bằng đôi tay của mình.","Không thể phá bỏ lời thề của vua, ta có một sứ mệnh phải hoàn thành, nguyện vọng của ta ngay từ đầu chỉ có một, lời thề này sẽ không bao giờ thay đổi kể từ lúc ta rút kiếm ra.","Một ngày nào đó, chắc chắn ta sẽ tìm được cách để tha thứ cho chính mình.","Ta muốn cứu quê hương của mình, muốn thay đổi số phận sụp đổ của nước Anh."}}
TAB_HeroFavorGift[44401] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Dù ta còn trẻ nhưng cũng là một người phụ nữ.","Sailor Moon của tình yêu và công lý, Sailor Moon, ta muốn thay mặt cho mặt trăng trừng phạt ngươi.","Bạch mã hoàng tử trong lòng ta là người sẽ đến cứu ta ngay lập tức khi có nguy hiểm.","Đại diện cho mặt trăng để tiêu diệt ngươi!"}}
TAB_HeroFavorGift[44403] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Anh hùng bất diệt!","Thiên thần hộ mệnh sắp đến!","Ta là thiên sứ thủ hộ của ngươi."}}
TAB_HeroFavorGift[44506] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Chúng ta nhất định sẽ thắng, là người sẽ nói chuyện thắng thua, nữ thần chiến thắng sẽ không cười nhạo ngươi. Nữ thần chiến thắng sẽ chỉ cười nhạo những kẻ luôn có trái tim nóng","Ai cũng thể hiện sự rực rỡ của mình vì cuộc sống và trưởng thành, dù có già đi thì cuộc đời vẫn có niềm vui, nỗi buồn và tình yêu.","Thế giới này không hề yếu đuối, cần có đầy đủ sức mạnh để cố gắng sống và hướng tới tương lai.","Những thứ trước mắt ngày càng sạch sẽ trên tay ta, như thể tâm hồn ta đã được rửa tội."}}
TAB_HeroFavorGift[44507] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Vì yêu, con người có thể rất dịu dàng, nhưng cũng rất mạnh mẽ! Trong cuộc đời không ai là không diệt một con sâu, không ngắt một cành hoa.","Con người không phải là thần thánh, vì vậy dù có lương thiện thế nào cũng sẽ vô ý làm chút điều xấu. Đây chính là cuộc sống. Vì cuộc sống nên chỉ có thể làm như thế.","Ngươi đã bỏ rơi tình bạn và nước mắt thì không có hy vọng chiến thắng nữa!","Ưu và khuyết điểm của Saint Seiya không ở chỗ thánh y, quan trọng nhất ai có thể đốt cháy vũ trụ nhỏ của chính mình sẽ giành chiến thắng!"}}
TAB_HeroFavorGift[44508] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Ta luôn nghĩ mình là một người không có ưu điểm gì, và sẽ không bao giờ giúp đỡ được ai hay có tác dụng nào. Cuối cùng, ta sẽ chỉ sống một cách tầm thường! Mặc dù điều đó khiến ta rất không cam tâm, cũng rất cô đơn, nhưng cũng không có cách nào... ta nghĩ như vậy. ","Không cần phải nguyền rủa ai nữa, không còn sát thương ai nữa. Tất cả nhân quả đều do ta gánh chịu, vậy nên hãy tin vào chính mình cho đến cùng.","Thần cũng tốt, mọi thứ đều tốt. Những thiếu nữ Ma Pháp trước nay đều tin tưởng hy vọng vào cuộc chiến ma nữ, ta không muốn làm họ khóc, hy vọng đến cuối cùng họ có thể tiếp tục mỉm cười, và những quy tắc cản trở những điều này là do ta phá bỏ nó, hãy nhìn ta và thay đổi nó, đây là mong muốn của ta.","Nếu ai đó nói với ta rằng hy vọng là một điều sai trái, ta sẽ phản bác chống lại dù có bao nhiêu lần đi nữa, bất kể khi nào ta vẫn kiên quyết như vậy."}}
TAB_HeroFavorGift[51502] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Ta không phải là một anh hùng chính nghĩa. Nhưng sẽ không bao giờ tha thứ cho những kẻ làm hại đồng đội ta!","Ta chiến đấu không phải vì chiến thắng cũng không phải để thất bại, ta chiến đấu chỉ vì những người đồng đội được sống tiếp, thế giới sẽ ổn định!","Kẻ mạnh nên hướng dẫn những người có thực lực chênh lệch quá lớn, người có thực lực tương đương phù hợp để tỉ thí và lớn lên cùng nhau!","Ta là một Saiyan lớn lên trên trái đất!"}}
TAB_HeroFavorGift[51507] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Saint Seiya, nếu ngươi thực sự nghĩ về Athena, đừng hành động hấp tấp.","Đối với loài người các ngươi, Thần Minh có lẽ là đối tượng của sự kính nể, nhưng bây giờ ngươi đã quên trái tim ngoan đạo đó.","Loài người chẳng qua chỉ là loài người, hợp lực có thể đánh bại được thần sao?"}}
TAB_HeroFavorGift[51508] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Trước sáng tạo đó là sự hủy diệt.","Ta là đại thần! Chỉ có một điều ta không thể chịu đựng được đó là thiếu tôn trọng và coi thường cảm xúc của người khác!","Phải biết từ bỏ đó cũng là điều rất quan trọng."}}
TAB_HeroFavorGift[51509] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Thứ trả giá bằng sinh mệnh của Rin căn bản không tồn tại.","Tenseiga để ta cứu loài người sao?","Nửa yêu nên có bộ dạng của giống nửa yêu... hãy nằm xuống.","Tên đó sao rồi, hắn biến mất vì nhút nhát? Hay là hắn không sẵn lòng giúp đỡ anh cả này một tay."}}
TAB_HeroFavorGift[52403] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Ta chỉ là một chấp sự.","Ta không quan tâm đến rác do con người tạo ra. Bởi vì ta là một con ác ma đồng thời là một chấp sự.","Hy sinh. Ước vọng. Ta vì khế ước mà bị chủ nhân ràng buộc, cho đến khi linh hồn của hắn tan biến.","Một khi ngươi từ chối đức tín ngưỡng sẽ không thể bước vào cánh cửa Thần nữa."}}
TAB_HeroFavorGift[52404] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Ta thấy bầu trời dường như có thể khóc bất cứ lúc nào, chắc ta cũng từ đó mà rơi xuống.","Không được gọi chúng ta là đồng chí nữa, chúng ta không có mối quan hệ đơn giản như vậy.","Sống trong thế giới nhàm chán này, nếu không tin vào một phép màu nào, ngươi sẽ không thể làm gì được.","Ta chỉ muốn phá hủy thế giới này."}}
TAB_HeroFavorGift[52501] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Một ngày nào đó, con người sẽ mất đi. Nhưng, chỉ cần ai đó tiếp tục bảo vệ niềm tin của mình, thì niềm tin này sẽ không lụi tàn. Nếu đã quyết định bảo vệ niềm tin của mình thì dù đau đớn bao nhiêu, rơi bao nhiêu nước mắt cũng phải quán triệt đến cùng. Đây mới là kỵ sĩ.","Ta đã cố gắng bảo vệ, mong muốn bảo vệ mọi thứ. Nhưng... ta không làm được, đó là lỗi của ta. Vì vậy, lần này, ta phải bảo vệ nó.","Ta sẽ giữ lời hứa với ngươi, ngay cả khi ngươi không còn."}}
TAB_HeroFavorGift[52510] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Ta đang mong chờ sự hủy diệt này.","Không thể tha thứ, Dạ Xoa Vương không thể tha thứ.","Hãy khóc đi, hãy gọi đi Giới Thiên Không ơi, rồi bước đến sự hủy diệt nào!"}}
TAB_HeroFavorGift[52511] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Không có gì thì không cần đến việc tốt này, thậm chí nên nói rằng không có gì quý hơn miễn phí.","Ta rất cứng đầu.","Sự ung dung của ngươi sẽ bị ta phá vỡ."}}
TAB_HeroFavorGift[53402] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Thần toàn năng! Con cầu xin ngài cho con thêm một cơ hội! Lần này con nhất định... nhất định sẽ... để tất cả những gì tốt đẹp trên thế giới vào trong tay!","Con thích một thế giới nơi mọi thứ đều được thương yêu, ngay cả khi ta không thể chạm vào nơi đó.","Thật đáng ghét. Rõ ràng là sát khí mạnh mẽ như vậy. Dù ngay cả như vậy... bản thân vẫn thề rằng sẽ thương xót và yêu tất cả. Vì vậy, đây là sự phản bội tuyệt vọng của chính mình."}}
TAB_HeroFavorGift[53505] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Đừng chạm vào ta... Ta cực kỳ tà ác!","Hãy để nỗi sợ hãi thống trị mọi thứ của ngươi!","Cuộc thám hiểm xa xôi và khó khăn kết thúc ở đây, người chính trực chân chính sẽ do số phận lựa chọn.","Hãy run rẩy đi, hồi chuông báo tử đã vang lên! Hãy run lên, Dirge đã hát cho ngươi! Ngày tận thế đã đến, toàn bộ sinh vật sẽ phải trả giá!"}}
TAB_HeroFavorGift[54401] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Ta nghĩ rằng nếu nói thế giới này là sai, thì mọi thứ tồn tại trên thế giới này đều phải chịu trách nhiệm cho sai lầm này.","Ta không phải là nhân vật gì cả, chỉ là một sinh viên đại học bình thường có thể nhìn thấy khắp nơi trên đường phố. Nhưng nếu viết một tác phẩm có nhân vật chính là ta, thì nó nhất định là một bi kịch... ","Người sai không phải ta mà là thế giới này!","Ta nắm tay ta, nó giống như vượt qua những rạn nứt của những ký ức vụn vỡ được lưu giữ bởi bộ não. Không nơi nào để chạy, loạng choạng không mục đích."}}
TAB_HeroFavorGift[54506] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Mặc dù đây là một thế giới vô vọng với những nỗi buồn và hận thù lặp đi lặp lại. Sau tất cả, đây là nơi mà cô ấy đã cố gắng bảo vệ. Ta sẽ ghi nhớ điều này và không bao giờ từ bỏ.","Dù có luân hồi bao nhiêu lần, ta vẫn lựa chọn luân hồi, tìm kiếm vô số lần, tìm lối ra duy nhất, tìm ra con đường có thể cứu ngươi khỏi số phận tuyệt vọng. Madoka, người bạn duy nhất của ta, cho dù có rơi vào mê cung vĩnh hằng vì ngươi, ta cũng sẽ không bận tâm!","Nếu mất ngươi sẽ có người đau lòng, sao ngươi không thể để ý? Người muốn che chở cho ngươi thì sao?","Đúng rồi, dù chịu tội lớn đến đâu, trở thành bộ dạng thế nào cũng không sao, miễn là có ngươi ở bên cạnh."}}
TAB_HeroFavorGift[41511] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Tên thật của ta là Gioanna! Ta sẽ trở thành lá chắn vững chắc cho mọi người!","Sinh mệnh chúng ta đúng là bị ràng buộc bởi những ham muốn ích kỷ, dù có trở thành những anh linh thì điều đó vẫn không thay đổi.","Xin cho ta được vẫy lá cờ này một lần nữa vì cứu nước, không, vì cứu thế giới.","Nghe này, những anh linh bất khuất tụ tập trong vùng này! Dù là kẻ địch không đội trời chung, dù là người ở thời đại khác nhau không có điểm giao nhau, xin hãy sát cánh bên nhau ngay từ bây giờ!"}}
TAB_HeroFavorGift[51512] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Đến nay, ta chưa bao giờ thua bất cứ ai, tốt nhất là nên giác ngộ nếu muốn chống lại ta.","Ta chỉ là một ác ma vô danh được Ác Vương mới triệu hồi ra.","Đối với ta được phục vụ chủ nhân là niềm vui lớn nhất."}}
TAB_HeroFavorGift[52513] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Kén vỡ thành bướm bay lên vẫn tốt hơn ta, không tồn tại trên đời.","Thời gian luân hồi, linh hồn ngươi cũng sẽ trở về trước mặt đất.","Hãy chăm chú nghe, đứa trẻ tội nghiệp này, những bước chân hủy diệt đang đến gần bên con.","Con không nên nói những điều dối trá lừa lọc, tất cả là do con người đã phản bội trái đất... "}}
TAB_HeroFavorGift[31510] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Ai cũng cầu được sống tiếp, ai cũng từng hy vọng được sống tiếp, sinh mệnh không phải là thứ đồ chơi để người ta giày vò!","Vì trách nhiệm nên mới đấu tay đôi.","Vì trái tim mách bảo với ta rằng bên đó mới là đúng đắn, ta phải đi con đường mà ta tin tưởng!","Con đao đáng nguyền rủa này không thích ngươi!"}}
TAB_HeroFavorGift[41512] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Ta là nữ thần Ishtar. Là nữ thần sắc đẹp cai quản sao Kim. Hãy bày tỏ sự kính trọng với ta.","Lẽ ra ta phải hấp dẫn hơn, nhưng cái thân này cũng không tệ.","Có hơi nóng, đã đến lúc phải cởi nó ra. Hả? Sao, ngươi thấy phiền không? Không được, để tạm đó đã. Nếu ngươi muốn say đắm ta thì phải đến lần nữa?"}}
TAB_HeroFavorGift[54514] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Gai đã cho ta một cái tên, một cái tên đã cho ta cả thế giới, nên ta không thể đi.","Tin vào chính mình, hoàn toàn có thể, bởi vì ta đã thuộc về ngươi.","Ta làm hết mình, không muốn lấy mạng người nên đừng đến đây.","Ta là quái vật cũng không quan trọng. Dù là cảm tình giả tạo, ta cũng muốn bảo vệ. Vì ta chính là ta. Ngay cả khi là giả, nhưng đó là sự chân thực duy nhất đối với ta!"}}
TAB_HeroFavorGift[43513] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Ta cần sự giúp đỡ của ngươi và hy vọng có thể tin tưởng ngươi.","Hãy tự hỏi bản thân rằng ngươi có thể hy sinh bao nhiêu cho niềm tin?","Chúng ta đến từ những thế giới khác nhau và có thể bị chia cắt vì một số lý do.","Ta sẽ tìm cách cứu mọi người."}}
TAB_HeroFavorGift[22516] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Ta là kẻ chinh phục mọi thứ, dù đó là ai.","Mặc dù có rất nhiều điều ta muốn nói với ngươi... nhưng khi nhìn thấy khuôn mặt ngươi, lại không nhớ ra hết.","Sau khi diệt địch, là phần thưởng thời gian vui vẻ.","Lần sau nếu ngươi còn thất bại, ta sẽ tự mình trừng phạt ngươi."}}
TAB_HeroFavorGift[63501] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Ta tên là Rimuru, một slime dễ thương, chắc chắn không phải là một slime xấu.","Ta dường như thực sự được tái sinh thành một slime, và những ngày trôi qua như thế này, phải nói rằng cơ thể thế này rất tiện lợi, thậm chí không ăn không ngủ vẫn có thể sống sót tung tăng.","Dù cố gắng đến đâu đều có những thứ không thể có được. Miễn là không biết những điều này ngay từ đầu thì ngươi sẽ không phải đau khổ vì nó.","Ta không phải là một slime tà ác~"}}
TAB_HeroFavorGift[51515] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Ta là người đứng trong bóng tối, dù chỉ một tia nắng nhỏ nhất cũng khiến tim ta đau nhói.","Ngươi nhờ vào sức mạnh của người khác vẫn mệt như vậy. Nếu hận thì hãy hận chính mình quá bất tài!","Ta có cách tồn tại của riêng mình và không ai có thể ra lệnh cho ta!"}}
TAB_HeroFavorGift[31517] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Trên đời này, chỉ cần có một thanh kiếm là có thể đến bất cứ nơi đâu.","Cuộc đời của ta thuộc về ngươi, Asuna. Vì vậy, ta dùng nó vì ngươi. Chúng ta hãy ở bên nhau đến giây phút cuối cùng.","Ta sẽ không từ bỏ, chỉ cần có thể nhìn thấy Asuna thì dù hắn là thần ta cũng phải đánh bại.","Khi ta rút thanh kiếm thứ hai, đó là để bảo vệ những người ta yêu thương."}}
TAB_HeroFavorGift[41514] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Tuyết chờ đến mùa xuân thì tan, chảy róc rách về nơi này---- ta sẽ ở đây chờ ngươi, khi hoa nở","A… sao ta quên chứ, người đó đặt tên cho ta---lật lại sự tồn tại của ta","Tên ta sao… ta tên là Yatogami Tohka, là cái tên quan trọng nhất của người quan trọng nhất đặt cho ta---rất hay đó!","Tiếp theo, để Tohka bên đó làm nhé, đừng để ‘Tohka’ cảm thấy đau lòng"}}
TAB_HeroFavorGift[53516] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Chính vì ta hiểu rõ duyên phận này, nên cần tự mình cắt đứt nó","Ta từng mất mọi thứ, vì vậy không muốn lại thấy các đồng đội yêu quý nhất ra đi trước mắt ta","Ta là kẻ báo thù, sống vì trả thù, để trả thù ta có thể từ bỏ tất cả","Những tiếng cười đó giờ với ta là sự mỉa mai và chế nhạo!! Ta đem những tiếng cười đó thành nổi đau và sự gào thét!!"}}
TAB_HeroFavorGift[64502] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Miếng đất lớn này là vườn ươm quan trọng nhất của ta, ta không cho phép nó bị phá hoại lần nữa","Ta sẽ ở đây, tiêu diệt hết các ngươi","Hai đứa nhỏ này là Vũ Y và Vũ Thôn..., không, là Indora và Ashura à?","Ta hận các ngươi, Vũ Y, Vũ Thôn."}}
TAB_HeroFavorGift[42515] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Nếu ngươi là Ma nữ, ta chỉ cần trở thành Ma Vương là được","Người có tư cách nổ súng, chỉ khi có linh cảm bị bắn hạ","Không thể bất lực, sức mạnh đó là chính nghĩa sao? Không thể phục thù sao? Tình bạn xứng đáng với chính nghĩa?","Ta, hủy diệt thế giới, cũng tạo ra thế giới"}}
TAB_HeroFavorGift[52517] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Cướp thanh xuân của người khác là hành vi không thể tha thứ.","Không sao, ta mạnh nhất.","Quá tốt rồi, ta vẫn lo, nếu như ngươi quá khiếp sợ thì phải làm sao.","Trước mặt học sinh mà, để ta 'ra dẻ' tý nào."}}
TAB_HeroFavorGift[61503] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Ta là Yhwach, sẽ lấy đi của ngươi tất cả!","Sức mạnh toàn trí toàn năng không phải nhìn thấy tương lai mà là thay đổi tương lai!","Nhưng, rất tiếc, cho dù bị diệt trừ một nửa sức mạnh; ta vẫn có thể cho bản thân sức mạnh thêm lần nữa!","Hãy trả lại sức mạnh ta cho ngươi đi!"}}
TAB_HeroFavorGift[44516] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Nếu đời người có 5 lần thì tốt quá, nếu vậy 5 lần ta đều muốn sống ở những thành phố khác nhau, 5 lần đều muốn ăn những thứ khác nhau, ăn no nê, 5 lần đều muốn làm công việc khác nhau… rồi 5 lần đều muốn thích cùng một người.","Nếu ta là giọt mưa đó… vậy thì, ta có thể kết nối bầu trời và mặt đất chưa từng gặp nhau lại, như vậy… có móc nối trái tim người nào đó lại được không","Chúng ta đó, mỗi người là sự tồn tại không hòa lẫn nhau; hai người không có dáng vẻ giống nhau; ba con mắt, không ai có mắt như vậy; nhìn tứ phương, dường như không thấy hi vọng; chỗ thứ 5, có một sự tồn tại gọi là trái tim","Ichigo, ta có rất nhiều việc muốn làm. Ta muốn làm giáo viên ở trường… cám ơn cậu, Ichigo, vĩnh biệt"}}
TAB_HeroFavorGift[54518] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Để chúng ta khiêu vũ nào, các chàng trai!","Phải phạt những đứa trẻ không lễ phép","Bây giờ niềm vui mới bắt đầu nè","Đồng đội ở địa ngục bảo ta y đói đến độ không chờ được, giờ ăn đến rồi, baby"}}
TAB_HeroFavorGift[43517] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Tên háo sắc ngươi! Ngốc nghếch! Biến thái! Thật không dám tin!","Đặc biệt cho phép người gọi ta là Asuka Langley, ta cũng sẽ gọi ngươi là Ikari Shinji ngốc","Ngươi ngốc sao? Đây không phải nơi ngươi có thể sống được. Là nơi ta cần bảo vệ!","Ta ngủ say rồi? Ikari Shinji ngốc?"}}
TAB_HeroFavorGift[62504] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"JOJO, năng lực con người có cực hạn, từ trong nhân sinh ngắn ngủi ta học được một việc… càng mưu kế, càng phát hiện năng lực nhân loại có hạn… trừ phi vượt qua nhân loại.","Nhân hành đạo không phải rất rộng sao? Mở xe cho ta!","Ồ, xem ta đi tới rồi chứ, không bỏ chạy mà chủ động tiếp cận ta sao; ông ngoại ngươi không dễ dàng thấy bí mật {Thế giới} của ta, giống như thí sinh vẫn đang trả lời câu hỏi khi kỳ thi sắp kết thúc vậy, liều mạng nói cho ngươi!","Huyết tộc Joestar thật quá thích hợp rồi! Ta quá HIGH!!"}}
TAB_HeroFavorGift[51519] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Cho dù không có Ma Lực ta cũng muốn trở thành Ma Pháp Vương, sẽ không bao giờ từ bỏ Ma Pháp","Từ lúc sinh ra ta là người không có Ma Lực nhưng vẫn muốn làm Ma Pháp Vương, ta tồn tại để chứng minh điều này.","Ta muốn trở thành Ma Pháp Vương bảo vệ Yuno, khiến mọi người sống tốt đẹp và hạnh phúc hơn, điều này cũng chứng minh rằng dù xuất thân nghèo khó, là đứa trẻ bị bỏ rơi cũng có thể trở thành Ma Pháp Vương.","Ta sẽ trở thành Ma Pháp Vương, điều này ta sẽ không bao giờ nhường cho một ai khác."}}
TAB_HeroFavorGift[41518] = {{{1, 5}, {2, 8}, {3, 10}, {4, 40}, {5, 80}, {6, 100}},6212,{3682, 3683, 3684},{3685, 3686, 3687},{"Việc ta muốn làm giờ đều làm được hết, đây là điểm cao nhất của ta. ","Không cần để ý, đến xem thắng bại nào!","Ta là Monkey D. Luffy, ta phải vượt qua ngươi, trở thành Vua Hải Tặc!","Ta phải kết thúc mọi chuyện, ta muốn... tạo ra... thế giới có thể khiến bạn bè ăn no... có thể khiến bạn bè ăn no!"}}
